// Blocks the game keeps a block entity for: a structure without one shows a bed or a chest broken (owner's walk-through:
// "broken beds") in loaders that don't create it on paste, so every one is written with at least its id.
const BLOCK_ENTITY = [
  [/_bed$/, "bed"], [/^(minecraft:)?(trapped_)?chest$/, (b) => (/trapped/.test(b) ? "trapped_chest" : "chest")], [/ender_chest$/, "ender_chest"], [/barrel$/, "barrel"],
  [/shulker_box$/, "shulker_box"], [/(^|:)furnace$/, "furnace"], [/smoker$/, "smoker"], [/blast_furnace$/, "blast_furnace"], [/hopper$/, "hopper"],
  [/dropper$/, "dropper"], [/dispenser$/, "dispenser"], [/lectern$/, "lectern"], [/(^|_)bell$/, "bell"], [/campfire$/, "campfire"], [/decorated_pot$/, "decorated_pot"],
  [/brewing_stand$/, "brewing_stand"], [/enchanting_table$/, "enchanting_table"], [/(beehive|bee_nest)$/, "beehive"], [/chiseled_bookshelf$/, "chiseled_bookshelf"],
  [/jukebox$/, "jukebox"], [/crafter$/, "crafter"], [/(^|_)banner$/, "banner"], [/(^|_)(wall_)?sign$/, "sign"], [/hanging_sign$/, "hanging_sign"],
  [/(skull|head)$/, "skull"], [/comparator$/, "comparator"], [/daylight_detector$/, "daylight_detector"],
];
function blockEntityOf(block) {
  const b = String(block);
  for (const [re, id] of BLOCK_ENTITY) if (re.test(b)) return `minecraft:${typeof id === "function" ? id(b) : id}`;
  return null;
}
// state keys a block needs that builders leave out (the game fills a default, some loaders don't)
const DEFAULT_STATE = [[/_bed$/, { occupied: "false" }]];
function withDefaults(c) {
  for (const [re, def] of DEFAULT_STATE) if (re.test(c.block)) { const st = { ...def, ...(c.state ?? {}) }; return { ...c, state: st }; }
  return c;
}

